// dispositionOps names, per disposition entry, the Huma operation(s) whose secured request the
// entry's coverage rests on. It is the machine-checkable half of a `CoveredByHTTPMiddleware` claim:
// prose can say "reached only via the secured deleteAccount operation" and be quietly wrong after a
// rename, a Security removal, or a route deletion — this cannot.
//
// TestDispositionOpsResolve asserts, for every operation named here, that it EXISTS in
// internal/huma/operations, is NOT a GET/HEAD/OPTIONS, and declares a non-empty Security. It also
// requires every dispositionCoveredByHTTPMiddleware entry to appear here, so the two maps cannot
// drift apart — an entry claiming middleware coverage without naming the operation that provides it
// is exactly the unverifiable shape #1537 set out to remove.
//
// Kept as a parallel map rather than a third struct field deliberately: adding a field would force
// all 197 positional entry literals to be rewritten, burying the substantive changes in a
// mechanical diff. The sync requirement above gives the same guarantee.
//
// Registration ORDER is not re-checked per entry — cmd/server's
// TestMutatingRoutesRegisteredAfterMiddlewareChain already proves globally that no secured route is
// registered before the middleware chain, which is stronger than a per-entry assertion would be.
var dispositionOps = map[string][]string{
	"AccountRepository.CreateBatch":                   {"exchangePublicToken"},
	"AccountRepository.Delete":                        {"deleteAccount"},
	"AccountRepository.Update":                        {"updateAccount"},
	"AccountRepository.UpdateDisplayOrders":           {"reorderAccounts"},
	"AccountRepository.UpdateStatus":                  {"exchangePublicToken"},
	"BudgetRepository.Create":                         {"createBudget"},
	"BudgetRepository.CreateWithCategories":           {"createBudget"},
	"BudgetRepository.Delete":                         {"deleteBudget"},
	"BudgetRepository.DeleteCategory":                 {"deleteBudgetCategory"},
	"BudgetRepository.Update":                         {"updateBudget"},
	"BudgetRepository.UpdateCategory":                 {"updateBudgetCategory"},
	"CustomCategoryRepository.Create":                 {"createCategory"},
	"CustomCategoryRepository.DeleteWithReassignment": {"deleteCategory"},
	"CustomCategoryRepository.Update":                 {"updateCategory"},
	"DashboardPreferencesRepository.Upsert":           {"saveDashboardPreferences"},
	"HouseholdInviteRepository.Create":                {"createHouseholdInvite"},
	"HouseholdInviteRepository.MarkDeclined":          {"declineHouseholdInvite"},
	"HouseholdInviteRepository.Revoke":                {"revokeHouseholdInvite"},
	"HouseholdRepository.CreateHousehold":             {"createHousehold"},
	"HouseholdRepository.DeleteHousehold":             {"deleteHousehold"},
	"HouseholdRepository.UpdateHouseholdName":         {"updateHouseholdName"},
	"LinkedItemRepository.DeleteByUser":               {"disconnectInstitution"},
	"MerchantOverrideRepo.BulkApply":                  {"bulkSetMerchantOverrides"},
	"MerchantOverrideRepo.Delete":                     {"clearMerchantOverride"},
	"MerchantOverrideRepo.MergeAndFlatten":            {"mergeMerchants"},
	"MerchantOverrideRepo.Upsert":                     {"setMerchantOverride"},
	// REMOVED (#1537 T40b): PrivacyRepository.{Create,CreateTx,Update}, RecipeRepository.{Create,
	// Delete,Update} and UserTagRepository.{Create,Delete,Update} used to be listed here, naming
	// updatePrivacySettings / create-update-deleteMCPRecipe / create-update-deleteTag. All nine are
	// dispositionDerivedNoCacheImpact, and that verdict is PROVEN by write-set disjointness
	// (cache_completeness_write_set_test.go) — it does not rest on middleware coverage and never did.
	// Listing an operation here asserts "this entry's coverage comes from that operation's
	// invalidation middleware", which for a Derived entry is a claim about nothing; nine of the 44
	// keys were making it. They were dropped rather than re-dispositioned, because re-dispositioning
	// would have replaced a mechanical proof with prose. The invariant is now enforced (see
	// TestDispositionOpsResolve): every key in this map must be CoveredByHTTPMiddleware.
	"SavingsGoalRepository.Delete":             {"deleteSavingsGoal"},
	"TransactionRepository.BulkUpdateCategory": {"bulkUpdateTransactionCategory"},
	"TransactionRepository.SetReviewed":        {"setTransactionReviewed", "bulkSetTransactionReviewed"},
	"TransactionRepository.UpdateCategory":     {"updateTransactionCategory"},
	"TransactionRepository.UpdateTags":         {"updateTransactionTags"},
	"UserAccountRepository.Create":             {"exchangePublicToken"},
	"UserAccountRepository.Update":             {"updateUserAccount"},
	// CORRECTED (#1537 T40b): both of these named `updateUserAccount`, which cannot reach either
	// method. updateUserAccount's handler calls UpdateCustomization ONLY
	// (`huma/operations/user_account.go:94` → `services/user_account_service.go:203`), and
	// UpdateCustomization writes through `repo.Update`. The real routes, re-derived from the callers:
	// UpdateHidden has two, `normalizeExistingUserAccount` (via MatchOrCreate ← LinkAccounts ←
	// exchangePublicToken) and `SetHidden` (via accountService.DeleteAccount ← deleteAccount);
	// UpdatePrimaryTypeAndSubtype has only the first. Both entries' PROSE already named those
	// operations correctly — so the machine-checkable half contradicted the prose it was added to
	// verify, and TestDispositionOpsResolve did not notice, because it only asks whether the named
	// operation exists, is non-GET and declares Security. All three were true of updateUserAccount.
	"UserAccountRepository.UpdateHidden":                {"exchangePublicToken", "deleteAccount"},
	"UserAccountRepository.UpdatePrimaryTypeAndSubtype": {"exchangePublicToken"},
}

// scanMutatingRepoInterfaceMethods walks every non-test .go file directly in dir (no recursion),
// finds every `type X interface { ... }` declaration, and returns "X.MethodName" for every
// directly-declared (non-embedded) exported method whose name satisfies looksMutating.
//
// This is a syntax-only AST walk (go/parser, no type-checking): it does not resolve embedded
// interfaces, so a mutating method reached only through embedding would not be found here. No
// interface in this package currently embeds another that contributes a mutating method (verified
// by inspection while building this guard); a future one would need this scanner extended.
func scanMutatingRepoInterfaceMethods(dir string) (map[string]bool, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}

	found := map[string]bool{}
	fset := token.NewFileSet()
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}
		path := filepath.Join(dir, name)
		file, err := parser.ParseFile(fset, path, nil, 0)
		if err != nil {
			return nil, err
		}

		for _, decl := range file.Decls {
			gd, ok := decl.(*ast.GenDecl)
			if !ok || gd.Tok != token.TYPE {
				continue
			}
			for _, spec := range gd.Specs {
				ts, ok := spec.(*ast.TypeSpec)
				if !ok {
					continue
				}
				iface, ok := ts.Type.(*ast.InterfaceType)
				if !ok {
					continue
				}
				ifaceName := ts.Name.Name
				for _, m := range iface.Methods.List {
					if len(m.Names) == 0 {
						continue // embedded interface, not a directly-declared method
					}
					methodName := m.Names[0].Name
					if looksMutating(methodName) {
						found[ifaceName+"."+methodName] = true
					}
				}
			}
		}
	}
	return found, nil
}

// TestEveryMutatingRepoMethodIsInReviewedAllowlist is completeness guard #1 (see the package doc
// comment above for what it does and does NOT prove).
func TestEveryMutatingRepoMethodIsInReviewedAllowlist(t *testing.T) {
	found, err := scanMutatingRepoInterfaceMethods(".")
	if err != nil {
		t.Fatalf("scanning repository interfaces: %v", err)
	}
	if len(found) == 0 {
		t.Fatal("scanned zero mutating interface methods — guard is looking at the wrong directory " +
			"or looksMutating broke; a silently-empty scan is worse than no guard at all")
	}

	var missing []string
	for key := range found {
		d, ok := repoMethodDispositions[key]
		if !ok {
			missing = append(missing, key)
			continue
		}
		switch d.kind {
		case dispositionExplicitBump, dispositionCoveredByHTTPMiddleware, dispositionNoCacheImpact:
			if strings.TrimSpace(d.detail) == "" {
				t.Errorf("repoMethodDispositions[%q] has an empty detail — a bare entry defeats the "+
					"point of this guard", key)
			}
		case dispositionDerivedNoCacheImpact:
			// The inverse rule: a derived entry must NOT carry prose. Its claim is re-proven
			// mechanically every run, so a detail string here would be an unchecked human
			// assertion masquerading as evidence — exactly the failure mode #1537 exists to end.
			if strings.TrimSpace(d.detail) != "" {
				t.Errorf("repoMethodDispositions[%q] is dispositionDerivedNoCacheImpact but carries a "+
					"detail string. Derived entries are proven by write-set disjointness, not argued; "+
					"if the claim needs prose it is not derived — use dispositionNoCacheImpact.", key)
			}
		default:
			// Unreachable today. Present so that adding a new kind without deciding how the guard
			// treats it fails loudly instead of silently passing every entry that uses it.
			t.Errorf("repoMethodDispositions[%q] has disposition kind %d, which this guard does not "+
				"know how to validate — teach it, do not leave the kind unchecked", key, int(d.kind))
		}
	}

	if len(missing) > 0 {
		t.Errorf("%d mutating repository method(s) are missing from repoMethodDispositions "+
			"entirely: %s", len(missing), strings.Join(missing, ", "))
	}

}

// TestNoStaleDispositionEntries is the reverse direction: the guard above proves map ⊇ scan (no
// mutating method lacks an entry), and this proves scan ⊇ map (no entry describes a method that no
// longer exists). Without it the map can rot into fiction — an entry for a deleted or renamed
// method keeps its reassuring prose forever, and the detail-validation loop never even looks at it,
// because that loop iterates the SCAN, not the map. Zero stale entries today, so adding this costs
// nothing now and prevents the drift later.
func TestNoStaleDispositionEntries(t *testing.T) {
	found, err := scanMutatingRepoInterfaceMethods(".")
	if err != nil {
		t.Fatalf("scanning repository interfaces: %v", err)
	}
	if len(found) == 0 {
		t.Fatal("scanned zero mutating interface methods — a silently-empty scan would make every " +
			"map entry look stale")
	}
	var stale []string
	for key := range repoMethodDispositions {
		if !found[key] {
			stale = append(stale, key)
		}
	}
	sort.Strings(stale)
	if len(stale) > 0 {
		t.Errorf("%d disposition entr(ies) describe methods this package no longer declares: %s\n"+
			"Delete them. A stale entry is worse than a missing one: it reads as reviewed coverage "+
			"for something that does not exist, and if the name is ever reused the old prose is "+
			"silently inherited by a different method.", len(stale), strings.Join(stale, ", "))
	}
}
